"""Dataset of 55+ realistic Indian phone conversation turns covering English, Hindi, and Hinglish."""

from dataclasses import dataclass
from typing import Literal


@dataclass
class HinglishTestCase:
    id: str
    category: str
    text: str
    expected_style: Literal["pure_english", "pure_hindi", "hinglish"]
    expected_dominant: Literal["english", "hindi", "mixed"]
    context_notes: str


